SourceCode.Declaration:
/// <summary>
/// The Operator Transfers a peace of data to a certain field. Eg. the value of a combined header {ItemIdWHSLicensePlateId} to ItemId. 
/// </summary>
class TFMLogicStepOperatorTransferDataToField extends TFMLogicBlock implements TFMLogicStepOperatorInterface
{
    str                                 inputValue;
    str                                 outputField;

}

Method.Source:
public void new()
{
    super();
    outputs = TFMLogicInputOutputContainer::Construct();        
    outputs.addConnectionName('');
}

public Name blockName()
{
    str blockName = "Transfer Value to Field";
    str valueSetName = "Transfer %1 to %2";
    return inputValue ? strFmt(valueSetName, inputValue, outputField) : blockName;
}

/// <summary>
/// Gets or sets the left-side (input) value.
/// </summary>
/// <param name="_inputValue">The value to set.</param>
/// <returns>The current value.</returns>
[TFMParameter('', "Input value")]
public TFMFlowVariableContextLookupField parmInputValue(TFMFlowVariableContextLookupField _inputValue = inputValue)
{
    inputValue = _inputValue;

    return inputValue;
}

[TFMParameter('', "Output field")]
public str parmOutputField(str _outputField = outputField)
{
    outputField = _outputField;

    return outputField;
}

public str runLogic ( TFMRequestElement _request )
{
    str replacedValue = _request.replaceWithValue(inputValue);
    _request.addField(outputField, replacedValue, true);

    _request.makeLogEntry (strFmt('Added field %1 with the value "%2"', outputField, inputValue));
    return '';
}
